class Producto:
    def __init__(self, nombre, precio_base):
        self.nombre = nombre
        self.set_precio(precio_base)

    def set_precio(self, precio):
        if precio <= 0:
            raise ValueError("Precio no valido")
        self.__precio_base = precio

    def get_precio(self):
        return self.__precio_base

